from pathlib import Path
import json,csv,hashlib,numpy as np,collections
B=Path(__file__).parent;D=B.parent
R=json.loads((B/'raw-evidence/raw-events.json').read_text());I={x['tic']:x for x in json.loads((B/'raw-evidence/independent-results.json').read_text())};G=json.loads((B/'gaia-geometry.json').read_text());S=json.loads((B/'source-review.json').read_text());C={x['tic']:x for x in json.loads((B/'catalogue-review.json').read_text())};Q=[r for r in csv.DictReader((D/'queue.csv').open()) if r['batch']=='6'];out=[]
for q in Q:
 t=q['tic'];r=R[t];g=G[t];s=S[t];i=I[t];ev=[x for x in r['events'] if 'tc'in x];ep=r['representative_ephemeris'];ip=i.get('measurements',[]);complete=bool(ip);verdict='CONFIRMED' if complete else 'PLAUSIBLE';geo=g['conjunction'][g['closest_kind']];depths=[x['depth']*1000 for x in ev];ind=[x['depth']*1000 for x in ip]
 row=dict(position=q['position'],tic=t,physical_verdict=verdict,execution_completion='complete' if complete else 'incomplete: independent reduction unavailable',full_review_completion='complete' if complete else 'incomplete',novelty_status=C[t]['scoped_prior_eb_status'],raw_events=len(ev),phot_period_d=ep['period_d'],timing_rms_min=ep['residual_rms_min'],raw_depth_median_ppt=float(np.median(depths)),gaia_period_d=g['gaia_P'],gaia_period_sigma=g['period_difference_gaia_sigma'],conjunction_offset_d=geo['offset_d'],conjunction_linear_cov_error_d=geo['covariance_linear_error_d'],diff_target_offset_arcsec=s['target_distance_arcsec'],capable_neighbours=len(s['capable']),independent_pipeline=i.get('provenance','unavailable'),independent_sector=i.get('sector',''),independent_depths_ppt=json.dumps(ind),report=f'TIC-{t}.md',next_deciding_test='No unresolved physical veto; resolved multiband eclipse photometry would improve dilution and radii.' if complete else 'Obtain independent extraction of representative eclipses.',note='Representative fits; cycle counts conditional; characterization and depth differences are not new gates.')
 out.append(row)
 text=f'''# TIC {t}

{verdict}. Full review execution: {row['execution_completion']}. Scoped novelty: {row['novelty_status']}.

Raw repetition and eclipse period: QLP SAP_FLUX with QUALITY=0 yields {len(ev)} representative events in sectors {sorted(set(x['sector'] for x in ev))}, fitted depths {min(depths):.2f}-{max(depths):.2f} ppt. A quadratic local baseline plus trapezoid derives P={ep['period_d']:.9f} d from event centres, timing RMS {ep['residual_rms_min']:.3f} min. Fits use native cadence without exposure integration; timing fits are unweighted and conditional on search cycle counts, without a fitted uncertainty. A two-event zero residual is algebraic, not a precision claim. A fresh GPT-6.1 Terra helper reviewed the raw repetitions and independent reduction; see raw-evidence/rawhelper-summary.md and raw-evidence/pixel-independent-results.json.

Source attribution: {s['source_assessment']}

'''
 for n in s['capable']:text+=f"Flux-capable Gaia DR3 {n['source_id']}: separation {n['sep']:.2f} arcsec, required eclipse loss {100*n['depth_needed']:.2f}%, own-pixel loss {100*n['frac_loss_at_pixel']:.2f}%, deficit distance {n['deficit_distance_arcsec']:.2f} arcsec. Own-pixel flux is mixed and does not alone exclude contamination.\n\n"
 for n in s.get('nearby_catalogued_eb_checks',[]):text+=f"Nearby catalogue EB Gaia DR3 {n['source_id']}: G={n['G']:.3f}, required fractional flux loss {n['depth_needed']:.2f} (greater than unity, hence not G-band flux-capable).\n\n"
 if ip:
  text+=f"Independent reduction: {i['provenance']}, sector {i['sector']}, repeats eclipse depths {', '.join(f'{x:.2f}' for x in ind)} ppt. "
  if 'TESScut' in i['provenance']:text+='Custom target aperture extraction of the same TESS photons supplies an independent reduction, not an independent observation or a SPOC product. Its local baseline/core medians and aperture dilution need not equal QLP trapezoid depths. '
  else:text+='The separate archived light-curve product uses a fixed QLP-measured event shape; the template ties timing/shape but not the independent flux extraction. '
  text+='Product/cutout identity, method, measurements and SHA256 are in raw-evidence/independent-results.json. Product-inventory failures are preserved, not treated as negative observations.\n\n'
 else:text+=f"Independent reduction unavailable: {i.get('error')}. This is incomplete execution.\n\n"
 text+=f"Gaia orbit geometry: SB1 P={g['gaia_P']:.9f} d, photometric difference {g['period_difference_gaia_sigma']:.2f} Gaia sigma. Closest edge-on conjunction {g['closest_kind']} offset {geo['offset_d']:.5f} d versus full SB1 covariance linear error {geo['covariance_linear_error_d']:.5f} d. Neither period nor conjunction reveals a strong contradiction. Observed median duration {g['observed_duration_hours_median']:.2f} h versus approximate central main-sequence feasibility {g['central_duration_hours_approx']:.2f} h; mass function {g['mass_function']:.5f} solar masses. This is an orbit feasibility check, not fitted inclination, stellar radii or a unique geometry. Linear propagation may be approximate for nearly circular orbits; covariance order and assumptions are preserved in gaia_geometry.py.\n\n"
 text+=f"Novelty: seven-scope central matrix reports {C[t]['scoped_prior_eb_status']}; coverage {C[t]['coverage_complete']}. Exact IDs and neighbours are separated in catalogue-review.json. SIMBAD SB* and ROT/VAR do not classify an EB; Kostov table2 is unvetted. Historical five-arcsec batteries retain condensed receipts; VSX/ASAS-SN cones are 60 arcsec. Alternate identities and catalogue versions limit this scoped result. Separate open-release comparison found no exact Gaia/TIC overlap in available tables; the embargoed 93-system release overlap is unknown and is not an additional EB gate. See ../shared-catalogues/README.md.\n\n"
 text+=f"Next deciding test: {row['next_deciding_test']}\n\nEvidence: raw-evidence/raw-events.json, raw-evidence/qlp-manifest.json, raw-evidence/independent-results.json, source-review.json, gaia-geometry.json, catalogue-review.json, lead-input-provenance.json and MANIFEST-SHA256.json.\n"
 (B/f'TIC-{t}.md').write_text(text,encoding='utf-8')
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,list(out[0]));w.writeheader();w.writerows(out)
